// Layout changes do not alter the save schema or the game rules.
const mobileQuery=matchMedia('(max-width:900px), (max-height:540px) and (orientation:landscape)');
let mobileUI=mobileQuery.matches;
document.body.classList.toggle('mobile-ui',mobileUI);

// Only the short memory cue appears while moving. Full questions wait for the safe stop.
const show=!!near&&(!mobileUI||waiting||peek);
$('gatePanel').hidden=!show;
if(show){
 if(!waiting)document.body.dataset.gateState='preview';

if(mobileUI){
 clearLabels();
 if(waiting&&g){
  const encouragement=dialogue.current?.id==='encourage'&&settings.captions;
  const encourageLine=encouragement?RAYYAN_LINES.find(l=>l.id==='encourage'):null;
  document.body.classList.toggle('compact-encourage',!!encouragement);
  const note=encourageLine?(settings.lang==='ar'?encourageLine.ar:encourageLine.en):T(retryHint?'retryCompact':'chooseCompact');
  if($('mobileChoiceNote').textContent!==note)$('mobileChoiceNote').textContent=note;
  $('mobileChoiceNote').classList.toggle('retry',retryHint);
  [...$('mobileChoices').children].forEach((b,i)=>{
   const txt=g.options[i],chosen=p.lane===i-1;
   if(b.firstElementChild.textContent!==txt)b.firstElementChild.textContent=txt;
   b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen));
   b.setAttribute('aria-label',T(['laneLeft','laneMiddle','laneRight'][i])+': '+txt);
  });
 }
}else

mobileUI?T('mobileIntro'):touch?T('guideMobile'):T('audioNote')}</p><div class="modal-actions">${btn('introGo','close','primary')}${btn('settings','settings')}${btn('wordsShort','words')}</div>`);
 if(kind==='mobileHelp'){
  const g=mode==='run'?run?.gates.find(x=>!x.done):null;
  const c=run?.chapter??selected;
  let body=`<p class="help-paused">${T('helpPaused')}</p><h3>${T(mode==='hub'?'hubTitle':chapterKeys[c])}</h3><p>${T(mode==='hub'?'hubText':chapterKeys[c]+'D')}</p>`;
  if(g&&g.d-run.d<72)body+=`<div class="help-current"><h3>${T(g.question)}</h3>${g.pattern?`<p class="help-pattern" dir="ltr">${escapeHTML(g.pattern)}</p>`:''}<p>${T(g.hint)}</p></div>`;
  body+=`<p>${T(mode==='hub'?'guideFree':'mobileIntro')}</p><div class="modal-actions">${btn('resume','close','primary')}${btn('controls','guide')}${btn('settings','settings')}</div>`;
  html=modalShell('helpTask',body,'helpShort');
 }

$('mobileHelp').onclick=()=>showNamedModal('mobileHelp');
$('mobileChoices').addEventListener('click',e=>{
 const b=e.target.closest('[data-lane-choice]');if(!b||!run?.waiting||modalKind)return;
 setLane(Number(b.dataset.laneChoice)-player.lane);
});
// Let focused choice buttons handle Enter/Space; do not bubble to the game's confirm/jump keys.
$('mobileChoices').addEventListener('keydown',e=>{if(e.code==='Enter'||e.code==='Space')e.stopPropagation();});
if('ResizeObserver' in window)new ResizeObserver(()=>{
 const r=$('gatePanel').getBoundingClientRect();
 document.body.style.setProperty('--mobile-question-end',Math.ceil(r.bottom+8)+'px');
}).observe($('gatePanel'));
function resizeLayout(){mobileUI=mobileQuery.matches;document.body.classList.toggle('mobile-ui',mobileUI);renderer.resize();updateHud();dialogue.layout();}
mobileQuery.addEventListener('change',resizeLayout);
